    public function matrix():array
    {
        $members=[];foreach($this->store->memberships() as $row)$members[(int)$row['user_id']][(string)$row['category']]=true;$rows=[];foreach($this->store->allUsers() as $user){$user['categories']=array_keys($members[(int)$user['id']]??[]);$user=$this->protected?->decorate($user)??($user+['protected'=>false,'protected_categories'=>[]]);unset($user['id'],$user['employee_id'],$user['employee_public_id'],$user['employment_status']);$rows[]=$user;}return ['categories'=>$this->categories,'users'=>$rows];
