        $current=[];foreach($this->store->memberships() as $row)$current[(int)$row['user_id']][(string)$row['category']]=true;$desired=$current;foreach($submitted as $publicId){$user=$byPublic[$publicId];$desired[(int)$user['id']]=[];$categories=$selected[$publicId]??[];if(!is_array($categories))throw new \InvalidArgumentException('Invalid category selection.');foreach($categories as $category=>$checked){if(!is_string($category)||!array_key_exists($category,$this->categories))throw new \InvalidArgumentException('An unknown category was submitted.');if($checked!==true)throw new \InvalidArgumentException('Invalid category checkbox value.');$desired[(int)$user['id']][$category]=true;}}
        foreach($submitted as $publicId)$this->protected?->assertCategoryBaseline($byPublic[$publicId],$desired[(int)$byPublic[$publicId]['id']]??[],$actor);$actorDesired=$desired[$actor->id]??[];if(isset($current[$actor->id]['admin'])&&!isset($actorDesired['admin']))throw new \InvalidArgumentException('You cannot remove your own Admin access.');$activeAdmins=0;foreach($all as $user)if($user['status']==='active'&&isset($desired[(int)$user['id']]['admin']))$activeAdmins++;if($activeAdmins===0)throw new \InvalidArgumentException('At least one active Gateway user must retain Admin access.');
